%[text] # 3 Laboras
%%
%[text] ## 1
clc;clear;
% a) 
figure;  %[output:530357e3]
t = linspace(-pi, pi, 50);
y_t = sin(t);

plot(t, y_t, 'r--', 'LineWidth', 1); %[output:530357e3]
title('Funkcija y(t) = sin(t)'); %[output:530357e3]
xlabel('t'); %[output:530357e3]
ylabel('y(t)'); %[output:530357e3]
axis([min(t) max(t) min(y_t)-0.2 max(y_t)+0.2]);  %[output:530357e3]
grid on;  %[output:530357e3]

legend(["y(t) = sin(t)"], 'location','best') %[output:530357e3]

% b)  
figure;  %[output:30b1991f]
x = linspace(-pi, pi, 50); 
y1_x = -x.^2 + 9;
y2_x = x.^3 - 2*x.^2 - 9;

plot(x, y1_x, 'b-', 'LineWidth', 1); %[output:30b1991f]
hold on; %[output:30b1991f]
plot(x, y2_x, 'g-', 'LineWidth', 1); %[output:30b1991f]
hold off; %[output:30b1991f]

title('Funkcijų grafikai'); %[output:30b1991f]
xlabel('x'); %[output:30b1991f]
ylabel('y(x)'); %[output:30b1991f]


all_y = [y1_x, y2_x];
axis([min(x) max(x) min(all_y)-5 max(all_y)+5]); %[output:30b1991f]

grid on; %[output:30b1991f]

xlim([-3.14 3.14]) %[output:30b1991f]
ylim([-65 14]) %[output:30b1991f]
legend(["y(x) = -x^2 + 9", "y(x) = x^3 - 2x^2 - 9"], 'Location','best') %[output:30b1991f]

%%
%[text] ## 2
figure;  %[output:219393fe]

studentu_ivertinimai = [
    6  2  5  4;
    1  6  3  6;
    2  6  7  8;
    4  5  2  1;
    8  7  7  9;
    3  5  2  8
    ];

subplot(2, 1, 1);  %[output:219393fe]

bar(studentu_ivertinimai');  %[output:219393fe]
title('a) Studentų pažangumas pagal laboratorinius darbus'); %[output:219393fe]
xlabel('Laboratoriniai darbai (L.d.)'); %[output:219393fe]
ylabel('Pažymiai'); %[output:219393fe]
axis([0.5 4.5 0 10]);  %[output:219393fe]
grid on; %[output:219393fe]

legend('Jorune', 'Ieva', 'Edvinas', 'Vijus', 'Dominykas', 'Saule', 'Location', 'northeastoutside'); %[output:219393fe]

subplot(2, 1, 2);  %[output:219393fe]
laboratoriniu_vidurkiai = mean(studentu_ivertinimai); 

stem(laboratoriniu_vidurkiai, 'filled', 'LineWidth', 1);  %[output:219393fe]
title('b) Laboratorinių darbų vidurkiai'); %[output:219393fe]
xlabel('Laboratoriniai darbai (L.d.)'); %[output:219393fe]
ylabel('Vidurkis'); %[output:219393fe]
axis([0.5 4.5 0 10]);  %[output:219393fe]
grid on; %[output:219393fe]
%%
%[text] ## PAPILDOMA

figure;  %[output:2fef1db4]
%%IS ANTRO LABORO
amplitude=6;
daznis=2;
sigma=1.5;
U1=4;
U2=2;
laikas=(0:0.005:2);

h_sign=amplitude*cos(2*pi*daznis*laikas);
triuksmas=sigma*randn(size(laikas));
bendr_sign=h_sign+triuksmas;;

reiksmes_virs=bendr_sign(bendr_sign>U1);
filtruota=bendr_sign;;
filtruota(abs(filtruota)<U2)=0;
% a)
subplot(1, 2, 1);  %[output:2fef1db4]

% 2, 3 
plot(laikas, bendr_sign, 'b-', 'LineWidth', 1);  %[output:2fef1db4]
hold on; %[output:2fef1db4]
plot(laikas, filtruota, 'g:', 'LineWidth', 1); %[output:2fef1db4]

yline(U1, 'r--', 'LineWidth', 1, 'DisplayName', 'U_1 riba'); %[output:2fef1db4]
yline(U2, 'r-.', 'LineWidth', 1, 'DisplayName', 'U_2 riba');  %[output:2fef1db4]
hold off; %[output:2fef1db4]

title('Pradinis ir filtruotas signalai'); %[output:2fef1db4]
xlabel('Laikas', 'FontSize', 13, 'FontWeight', 'bold'); %[output:2fef1db4]
ylabel('Įtampa', 'FontSize', 13, 'FontWeight', 'bold'); %[output:2fef1db4]
legend('Pradinis signalas', 'Filtruotas signalas', 'U_1 riba', 'U_2 riba', 'Location', 'best'); %[output:2fef1db4]
grid on; %[output:2fef1db4]
axis([min(laikas) max(laikas) min(bendr_sign)-1 max(bendr_sign)+1]); %[output:2fef1db4]

% b) 
subplot(1, 2, 2);  %[output:2fef1db4]

idx = bendr_sign > U1;
t_virsk = laikas(idx);
signal_virsk = bendr_sign(idx);

stem(t_virsk, signal_virsk, 'filled', 'LineWidth', 1.2); %[output:2fef1db4]
hold on; %[output:2fef1db4]

[max_val, max_idx] = max(signal_virsk);
[min_val, min_idx] = min(signal_virsk);

plot(t_virsk(max_idx), max_val, 'rp', 'MarkerSize', 9, 'MarkerFaceColor', 'r', 'DisplayName', 'Maksimali reikšmė'); %[output:2fef1db4]
plot(t_virsk(min_idx), min_val, 'ko', 'MarkerSize', 9, 'MarkerFaceColor', 'k', 'DisplayName', 'Minimali reikšmė'); %[output:2fef1db4]
hold off; %[output:2fef1db4]

title('Pradinio signalo reikšmės virš U_1'); %[output:2fef1db4]

xlabel('Laikas', 'FontSize', 13, 'FontWeight', 'bold'); %[output:2fef1db4]
ylabel('Įtampa', 'FontSize', 13, 'FontWeight', 'bold'); %[output:2fef1db4]
legend('Reikšmės > U_1', 'Maksimumas', 'Minimumas', 'Location', 'best'); %[output:2fef1db4]
grid on; %[output:2fef1db4]

